// How do I insert a new paragraph into a shape in a presentation?

// Create a shape, add a paragraph with text to it, and display the shape on the slide.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);
slide.RemoveAllObjects();

const fill = Api.CreateSolidFill(Api.RGB(255, 111, 61));
const stroke = Api.CreateStroke(0, Api.CreateNoFill());
const shape = Api.CreateShape("flowChartMagneticTape", 300 * 36000, 130 * 36000, fill, stroke);
shape.SetPosition(608400, 1267200);

const docContent = shape.GetDocContent();
docContent.RemoveAllElements();
const paragraph = Api.CreateParagraph();
paragraph.AddText("We removed all elements from the shape and added a new paragraph inside it.");
docContent.AddElement(0, paragraph);
slide.AddObject(shape);

// How do I add text to the last paragraph of a shape's document content in a presentation?

// Add a sentence to a shape without replacing its existing text in a presentation.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);
slide.RemoveAllObjects();

const fill = Api.CreateSolidFill(Api.HexColor('#E8D5B7'));
const stroke = Api.CreateStroke(0, Api.CreateNoFill());
const shape = Api.CreateShape('roundRect', Api.MillimetersToEmus(300), Api.MillimetersToEmus(130), fill, stroke);
shape.SetPosition(Api.MillimetersToEmus(20), Api.MillimetersToEmus(35));
const docContent = shape.GetContent();
docContent.GetElement(0).AddText('First sentence.');
docContent.AddText(' Appended sentence.');
const infoParagraph = Api.CreateParagraph();
infoParagraph.AddText('Text from document content: ' + docContent.GetText());
docContent.Push(infoParagraph);
slide.AddObject(shape);

// How do I access every paragraph inside a shape in a presentation?

// Retrieve the complete list of paragraphs from a shape and format the first one.

const presentation = Api.GetPresentation();
const slide = presentation.GetSlideByIndex(0);
slide.RemoveAllObjects();

const fill = Api.CreateSolidFill(Api.RGB(189, 215, 175));
const stroke = Api.CreateStroke(0, Api.CreateNoFill());
const shape = Api.CreateShape('rect', Api.MillimetersToEmus(300), Api.MillimetersToEmus(130), fill, stroke);
shape.SetPosition(Api.MillimetersToEmus(20), Api.MillimetersToEmus(35));
const docContent = shape.GetContent();

const paragraph1 = docContent.GetElement(0);
paragraph1.AddText('Paragraph 1');

const paragraph2 = Api.CreateParagraph();
paragraph2.AddText('Paragraph 2');
docContent.Push(paragraph2);

const allParagraphs = docContent.GetAllParagraphs();

allParagraphs[0].SetBold(true);
const infoParagraph = Api.CreateParagraph();
infoParagraph.AddText('Total paragraphs: ' + allParagraphs.length);
docContent.Push(infoParagraph);
slide.AddObject(shape);

